const D = { bands: 16, scale: 1, energy: .6, density: .5, hue: 28, speed: 1, x: .34, y: .42, alpha: 1, style: 'agate', act: 'slice', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, act=P.act;
const nBand=cl(P.bands,2,46), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=Math.max(360,Math.min(720,Math.round(W/2.4))), BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,720);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; }
const G=S.g;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let cutRate, accrete, sheenAmt;
if(act==='bloom'){ cutRate=.45; accrete=.74+.26*Math.sin(sec*.8+T*.019); sheenAmt=.85; }
else if(act==='still'){ cutRate=.42; accrete=1; sheenAmt=1.5; }
else { cutRate=1; accrete=1; sheenAmt=1; }

// ---- the lapidary's cut plane: it keeps slicing, so the bands migrate forever ----
const Z=4.7 + cutRate*(.030*TD + .18*Math.sin(TD*.037) + .09*Math.sin(TD*.089+1.7));
// polished-face light: azimuth orbits, elevation drifts
const lAz=cl(P.x,0,1)*TAU + .44*Math.sin(TD*.043) + .23*Math.sin(TD*.101+1.3) + .12*Math.sin(TD*.171+2.7);
const lx=Math.cos(lAz), ly=Math.sin(lAz);
const lEl=cl(P.y,0,1)*1.2 + .17*Math.sin(TD*.057+.5) + .08*Math.sin(TD*.119+2.4) + .04*K.swell;

// ---- style ----
let ROCK, VUG, spTint, polar=0, inkish=0, granAmt=.07, bandSat=1;
if(sty==='malachite'){ ROCK=hsb2rgb(H+112,30,7); VUG=hsb2rgb(H+108,42,66); spTint=[224,255,232]; granAmt=.05; }
else if(sty==='blue_lace'){ ROCK=hsb2rgb(H+168,26,10); VUG=hsb2rgb(H+172,12,86); spTint=[236,246,255]; granAmt=.06; }
else if(sty==='polarised'){ ROCK=hsb2rgb(H+180,12,5); VUG=hsb2rgb(H+150,70,88); spTint=[255,255,255]; polar=1; granAmt=.03; }
else if(sty==='ink'){ ROCK=hsb2rgb(H-4,22,12); VUG=hsb2rgb(H+2,7,86); spTint=[250,246,236]; inkish=1; granAmt=.12; bandSat=.42; }
else { ROCK=hsb2rgb(H-12,24,8); VUG=hsb2rgb(H+6,10,84); spTint=[255,248,232]; granAmt=.07; }

