const NBL=72;
const blK=P.seed+'|'+sty+'|'+Math.round(H)+'|'+Math.round(bandSat*10);
if(S.blK!==blK){ S.blK=blK; const BL=new Float32Array(NBL*3);
  for(let k=0;k<NBL;k++){
    const r1=fr(k*5.7+200), r2=fr(k*5.7+201), r3=fr(k*5.7+202);
    let hh,ss,bb;
    if(sty==='malachite'){ hh=H+104+r1*20; ss=(38+50*r2)*bandSat; bb=16+58*Math.pow(r3,.8); }
    else if(sty==='blue_lace'){ hh=H+150+r1*44; ss=(8+30*r2)*bandSat; bb=34+52*r3; }
    else if(sty==='polarised'){ hh=r1*360; ss=(52+44*r2)*bandSat; bb=26+62*r3; }
    else if(sty==='ink'){ hh=H-2+r1*10; ss=(4+16*r2)*bandSat; bb=14+70*Math.pow(r3,.7); }
    else { // agate — chalcedony: milk white, grey, honey, carnelian, a rare deep band
      const pick=r1;
      if(pick<.34){ hh=H+8+r2*14; ss=4+9*r2; bb=62+30*r3; }        // milky white / grey
      else if(pick<.66){ hh=H-2+r2*16; ss=32+34*r2; bb=40+34*r3; } // honey / amber
      else if(pick<.88){ hh=H-14+r2*12; ss=52+34*r2; bb=28+30*r3; }// carnelian
      else { hh=H+186+r2*26; ss=20+26*r2; bb=10+16*r3; }           // rare dark/blue band
      ss*=bandSat;
    }
    const c=hsb2rgb(hh,ss,bb); BL[k*3]=c[0]; BL[k*3+1]=c[1]; BL[k*3+2]=c[2];
  }
  S.bl=BL; }
const BL=S.bl;

// ---- the nodule: a smooth union of lobes whose radii breathe as the cut plane advances ----
const NLOB=Math.round(3+dens*4);
if(S.loK!==P.seed+'|'+NLOB){ S.loK=P.seed+'|'+NLOB; const LB=new Float32Array(NLOB*5);
  for(let k=0;k<NLOB;k++){
    LB[k*5]=(fr(k*9.1+300)-.5)*.72; LB[k*5+1]=(fr(k*9.1+301)-.5)*.56;
    LB[k*5+2]=.30+.28*fr(k*9.1+302);
    LB[k*5+3]=.5+1.3*fr(k*9.1+303); LB[k*5+4]=fr(k*9.1+304)*TAU;
  }
  S.lo=LB; }
const LB=S.lo;
const RAD=new Float32Array(NLOB);
for(let k=0;k<NLOB;k++) RAD[k]=LB[k*5+2]*sc*(.94+.26*Math.sin(Z*LB[k*5+3]+LB[k*5+4]))*accrete;
const smin=(a,b,k)=>{ const h=cl(.5+.5*(b-a)/k,0,1); return b*(1-h)+a*h-k*h*(1-h); };
const smK=.15*sc;

// ---- band geometry ----
const bandF=nBand/Math.max(.12,.62*sc);   // bands per unit of wall depth
const wallAmp=.030*sc*(.5+.9*dens);
const ph1=fr(11)*TAU, ph2=fr(12)*TAU;
const vugAt=nBand*.80;
const gran=granAmt*(.5+.9*dens);
const asp=W/Math.max(1,Hh);
const camD=.012*(1.0*Math.sin(TD*.061+.4)+.5*Math.sin(TD*.137+2.2));

G.loadPixels();
const px=G.pixels, sR=spTint[0], sG=spTint[1], sB=spTint[2];
const spAmt=(.22+.75*en)*sheenAmt*(.6+.6*K.intensity)+S.tre*.25*en;
for(let j=0;j<BH;j++){
  const sy=(j/BH-.5)+camD*.6;
  for(let i=0;i<BW;i++){
    const sx=(i/BW-.5)*asp+camD;
    // wall distance: smooth union of the lobes, then roughen the wall
    let u=1e9;
    for(let k=0;k<NLOB;k++){
      const dx=sx-LB[k*5], dy=sy-LB[k*5+1];
      const d=Math.sqrt(dx*dx+dy*dy)-RAD[k];
      u=(k===0)?d:smin(u,d,smK);
