      const g1=nzAt(sx*9.3+21.1, sy*9.3+13.7)-.5, g2=nzAt(sx*27.1-5.5, sy*27.1+2.2)-.5;
      const sp=1+(g1*1.5+g2*1.1)*(gran*3.4);
      const fade=cl(1-u*1.4,0,1);
      const v=(.55+.5*fade)*sp;
      R=ROCK[0]*v; Gc=ROCK[1]*v; B=ROCK[2]*v;
    } else {
