        const q1=nzAt(sx*34+41.1, sy*34+17.3), q2=nzAt(sx*61-8.8, sy*61+29.9);
        const fac=Math.pow(cl(q1*1.35+q2*.5-.35,0,1),1.5);
        const mixv=cl((dep-vugAt)/Math.max(1,nBand*.20),0,1);
