        R=R+(vr-R)*mixv; Gc=Gc+(vg-Gc)*mixv; B=B+(vb-B)*mixv;
      }
      if(inkish){ const m=(R*.3+Gc*.59+B*.11); R=R*.35+m*.65; Gc=Gc*.35+m*.65; B=B*.35+m*.65; }
