    const vx=(i/BW-.5), vy=(j/BH-.5), vg2=1-.34*(vx*vx*1.2+vy*vy*1.7);
    R*=vg2; Gc*=vg2; B*=vg2;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
